import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import 'package:intl/intl.dart';
import '../../../core/widgets/glass_card.dart';
import '../../../core/widgets/gradient_button.dart';
import '../services/finance_extension_service.dart';

/// Grant Management — research / government grants (UGC, DST, DBT...).
/// Grant list -> create grant; tapping a grant opens its detail with
/// head-wise expenses, add-expense and a Utilization Certificate (UC)
/// summary generated by FinanceExtensionService.generateUCData().
class GrantManagementScreen extends StatefulWidget {
  const GrantManagementScreen({super.key});

  @override
  State<GrantManagementScreen> createState() => _GrantManagementScreenState();
}

class _GrantManagementScreenState extends State<GrantManagementScreen> {
  final _service = FinanceExtensionService();
  bool _isLoading = true;
  List<Map<String, dynamic>> _grants = [];

  static const _bg = Color(0xFF0F0E17);
  static const _cardBg = Color(0xFF1A1A2E);
  static const _cardBg2 = Color(0xFF16213E);
  static const _primary = Color(0xFF6C5CE7);
  static const _accent = Color(0xFF00CEC9);
  static const _textSec = Color(0xFF9CA3AF);
  static const _border = Color(0xFF2D2D44);
  static const _ok = Color(0xFF00B894);
  static const _danger = Color(0xFFEF4444);

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    setState(() => _isLoading = true);
    final grants = await _service.getGrants();
    if (mounted) {
      setState(() {
        _grants = grants;
        _isLoading = false;
      });
    }
  }

  String _formatCurrency(dynamic v) {
    final n = (v is num) ? v.toDouble() : 0.0;
    if (n >= 10000000) return '₹${(n / 10000000).toStringAsFixed(2)} Cr';
    if (n >= 100000) return '₹${(n / 100000).toStringAsFixed(2)} L';
    if (n >= 1000) return '₹${(n / 1000).toStringAsFixed(1)}K';
    return '₹${n.toStringAsFixed(0)}';
  }

  void _toast(String msg, {bool error = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: error ? _danger : _ok,
      behavior: SnackBarBehavior.floating,
    ));
  }

  Widget _field(TextEditingController c, String label, IconData icon,
      {TextInputType? keyboard, String? Function(String?)? validator}) {
    return TextFormField(
      controller: c,
      style: const TextStyle(color: Colors.white),
      keyboardType: keyboard,
      validator: validator,
      decoration: InputDecoration(
        filled: true,
        fillColor: _cardBg2,
        border: OutlineInputBorder(
            borderRadius: BorderRadius.circular(10),
            borderSide: BorderSide.none),
        labelText: label,
        labelStyle: const TextStyle(color: _textSec),
        prefixIcon: Icon(icon, color: _textSec, size: 20),
      ),
    );
  }

  String? _required(String? v) =>
      (v == null || v.trim().isEmpty) ? 'Required' : null;

  String? _amount(String? v) {
    if (v == null || v.trim().isEmpty) return 'Required';
    if (double.tryParse(v.trim()) == null) return 'Enter a valid amount';
    return null;
  }

  Future<DateTime?> _pickDate(DateTime? initial) {
    return showDatePicker(
      context: context,
      initialDate: initial ?? DateTime.now(),
      firstDate: DateTime(2015),
      lastDate: DateTime(2100),
    );
  }

  // ---------------------------------------------------------------
  // CREATE GRANT DIALOG
  // ---------------------------------------------------------------
  void _showCreateGrantDialog() {
    final formKey = GlobalKey<FormState>();
    final grantNoC = TextEditingController();
    final titleC = TextEditingController();
    final agencyC = TextEditingController();
    final piC = TextEditingController();
    final sanctionedC = TextEditingController();
    final receivedC = TextEditingController(text: '0');
    DateTime? startDate;
    DateTime? endDate;
    bool saving = false;

    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setS) => AlertDialog(
          backgroundColor: _cardBg,
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
          title: const Text('Create Research Grant',
              style:
                  TextStyle(color: Colors.white, fontWeight: FontWeight.w700)),
          content: SizedBox(
            width: 480,
            child: Form(
              key: formKey,
              child: SingleChildScrollView(
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  _field(grantNoC, 'Grant / Sanction No', Icons.tag_rounded,
                      validator: _required),
                  const SizedBox(height: 12),
                  _field(titleC, 'Project Title', Icons.science_rounded,
                      validator: _required),
                  const SizedBox(height: 12),
                  Row(children: [
                    Expanded(
                        child: _field(agencyC, 'Funding Agency (UGC/DST...)',
                            Icons.account_balance_rounded,
                            validator: _required)),
                    const SizedBox(width: 12),
                    Expanded(
                        child: _field(piC, 'Principal Investigator',
                            Icons.person_rounded,
                            validator: _required)),
                  ]),
                  const SizedBox(height: 12),
                  Row(children: [
                    Expanded(
                        child: _field(
                            sanctionedC, 'Sanctioned (₹)', Icons.currency_rupee_rounded,
                            keyboard: TextInputType.number,
                            validator: _amount)),
                    const SizedBox(width: 12),
                    Expanded(
                        child: _field(
                            receivedC, 'Received (₹)', Icons.currency_rupee_rounded,
                            keyboard: TextInputType.number,
                            validator: _amount)),
                  ]),
                  const SizedBox(height: 12),
                  Row(children: [
                    Expanded(
                      child: OutlinedButton.icon(
                        style: OutlinedButton.styleFrom(
                          foregroundColor: _textSec,
                          side: const BorderSide(color: _border),
                        ),
                        icon: const Icon(Icons.calendar_today_rounded,
                            size: 16),
                        label: Text(startDate == null
                            ? 'Start Date'
                            : DateFormat('dd MMM yyyy').format(startDate!)),
                        onPressed: () async {
                          final d = await _pickDate(startDate);
                          if (d != null) setS(() => startDate = d);
                        },
                      ),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: OutlinedButton.icon(
                        style: OutlinedButton.styleFrom(
                          foregroundColor: _textSec,
                          side: const BorderSide(color: _border),
                        ),
                        icon: const Icon(Icons.event_rounded, size: 16),
                        label: Text(endDate == null
                            ? 'End Date'
                            : DateFormat('dd MMM yyyy').format(endDate!)),
                        onPressed: () async {
                          final d = await _pickDate(endDate);
                          if (d != null) setS(() => endDate = d);
                        },
                      ),
                    ),
                  ]),
                ]),
              ),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: const Text('Cancel', style: TextStyle(color: _textSec))),
            ElevatedButton(
              style: ElevatedButton.styleFrom(backgroundColor: _primary),
              onPressed: saving
                  ? null
                  : () async {
                      if (!formKey.currentState!.validate()) return;
                      setS(() => saving = true);
                      final ok = await _service.createGrant({
                        'grant_no': grantNoC.text.trim(),
                        'title': titleC.text.trim(),
                        'funding_agency': agencyC.text.trim(),
                        'principal_investigator': piC.text.trim(),
                        'sanctioned_amount':
                            double.tryParse(sanctionedC.text.trim()) ?? 0,
                        'received_amount':
                            double.tryParse(receivedC.text.trim()) ?? 0,
                        'start_date': startDate
                            ?.toIso8601String()
                            .split('T')
                            .first,
                        'end_date':
                            endDate?.toIso8601String().split('T').first,
                        'created_by': 'accountant',
                      });
                      if (!ctx.mounted) return;
                      Navigator.pop(ctx);
                      _toast(ok ? 'Grant created' : 'Grant creation failed',
                          error: !ok);
                      if (ok) _load();
                    },
              child:
                  const Text('Create', style: TextStyle(color: Colors.white)),
            ),
          ],
        ),
      ),
    );
  }

  // ---------------------------------------------------------------
  // BUILD — GRANT LIST
  // ---------------------------------------------------------------
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _bg,
      appBar: AppBar(
        backgroundColor: _cardBg,
        foregroundColor: Colors.white,
        elevation: 0,
        title: const Text('Grant Management',
            style: TextStyle(fontWeight: FontWeight.w700)),
        leading: IconButton(
          icon: const Icon(Icons.arrow_back_rounded),
          onPressed: () => context.go('/accountant-dashboard'),
        ),
        actions: [
          IconButton(
              icon: const Icon(Icons.refresh_rounded),
              tooltip: 'Refresh',
              onPressed: _load),
        ],
      ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _showCreateGrantDialog,
        backgroundColor: _primary,
        icon: const Icon(Icons.add_rounded, color: Colors.white),
        label: const Text('New Grant',
            style: TextStyle(color: Colors.white, fontWeight: FontWeight.w600)),
      ),
      body: _isLoading
          ? const Center(child: CircularProgressIndicator(color: _primary))
          : _grants.isEmpty
              ? _buildEmptyState()
              : RefreshIndicator(
                  color: _primary,
                  onRefresh: _load,
                  child: ListView.builder(
                    padding: const EdgeInsets.fromLTRB(16, 16, 16, 90),
                    itemCount: _grants.length,
                    itemBuilder: (ctx, i) => _buildGrantCard(_grants[i]),
                  ),
                ),
    );
  }

  Widget _buildEmptyState() {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(32),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Container(
            padding: const EdgeInsets.all(20),
            decoration: BoxDecoration(
              color: _primary.withOpacity(0.12),
              borderRadius: BorderRadius.circular(20),
            ),
            child: const Icon(Icons.science_rounded, color: _primary, size: 44),
          ),
          const SizedBox(height: 16),
          const Text('No grants yet',
              style: TextStyle(
                  color: Colors.white,
                  fontSize: 16,
                  fontWeight: FontWeight.w700)),
          const SizedBox(height: 8),
          const Text(
            'Add the first UGC / DST / research grant to start\ntracking sanction, receipts and utilization.',
            textAlign: TextAlign.center,
            style: TextStyle(color: _textSec, fontSize: 13),
          ),
        ]),
      ),
    );
  }

  Widget _buildGrantCard(Map<String, dynamic> g) {
    final sanctioned = (g['sanctioned_amount'] as num?)?.toDouble() ?? 0;
    final utilized = (g['utilized_amount'] as num?)?.toDouble() ?? 0;
    final pct = sanctioned > 0 ? (utilized / sanctioned) * 100 : 0.0;
    final status = (g['status'] as String?) ?? 'active';
    final statusColor = status == 'active'
        ? _ok
        : status == 'refunded'
            ? _danger
            : _textSec;
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: GlassCard(
        color: _cardBg,
        padding: const EdgeInsets.all(16),
        onTap: () async {
          await Navigator.of(context).push(MaterialPageRoute(
            builder: (_) => GrantDetailScreen(grant: g),
          ));
          _load();
        },
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Expanded(
              child: Text((g['title'] as String?) ?? 'Grant',
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.w700)),
            ),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
              decoration: BoxDecoration(
                color: statusColor.withOpacity(0.12),
                borderRadius: BorderRadius.circular(6),
              ),
              child: Text(status.toUpperCase(),
                  style: TextStyle(
                      color: statusColor,
                      fontSize: 10,
                      fontWeight: FontWeight.w700)),
            ),
          ]),
          const SizedBox(height: 6),
          Text(
            '${g['grant_no'] ?? ''} • ${g['funding_agency'] ?? ''} • PI: ${g['principal_investigator'] ?? ''}',
            style: const TextStyle(color: _textSec, fontSize: 12),
          ),
          const SizedBox(height: 12),
          ClipRRect(
            borderRadius: BorderRadius.circular(8),
            child: LinearProgressIndicator(
              value: (pct.clamp(0, 100)) / 100,
              minHeight: 8,
              backgroundColor: _border,
              valueColor: const AlwaysStoppedAnimation<Color>(_accent),
            ),
          ),
          const SizedBox(height: 8),
          Row(children: [
            Expanded(
                child: Text('Sanctioned: ${_formatCurrency(sanctioned)}',
                    style: const TextStyle(color: _textSec, fontSize: 12))),
            Text(
                'Used: ${_formatCurrency(utilized)} (${pct.toStringAsFixed(0)}%)',
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 12,
                    fontWeight: FontWeight.w600)),
          ]),
        ]),
      ),
    );
  }
}

/// Grant detail: UC summary card + head-wise expenses + add expense.
/// Opened from GrantManagementScreen when a grant card is tapped.
class GrantDetailScreen extends StatefulWidget {
  final Map<String, dynamic> grant;
  const GrantDetailScreen({super.key, required this.grant});

  @override
  State<GrantDetailScreen> createState() => _GrantDetailScreenState();
}

class _GrantDetailScreenState extends State<GrantDetailScreen> {
  final _service = FinanceExtensionService();
  bool _isLoading = true;
  Map<String, dynamic> _uc = {};
  List<Map<String, dynamic>> _expenses = [];

  static const _bg = Color(0xFF0F0E17);
  static const _cardBg = Color(0xFF1A1A2E);
  static const _cardBg2 = Color(0xFF16213E);
  static const _primary = Color(0xFF6C5CE7);
  static const _accent = Color(0xFF00CEC9);
  static const _textSec = Color(0xFF9CA3AF);
  static const _border = Color(0xFF2D2D44);
  static const _ok = Color(0xFF00B894);
  static const _danger = Color(0xFFEF4444);

  static const List<String> _heads = [
    'equipment',
    'manpower',
    'consumables',
    'travel',
    'overheads',
    'other',
  ];

  String get _grantId => widget.grant['id'].toString();

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    setState(() => _isLoading = true);
    final uc = await _service.generateUCData(_grantId);
    final expenses = await _service.getGrantExpenses(_grantId);
    if (mounted) {
      setState(() {
        _uc = uc;
        _expenses = expenses;
        _isLoading = false;
      });
    }
  }

  String _formatCurrency(dynamic v) {
    final n = (v is num) ? v.toDouble() : 0.0;
    if (n >= 10000000) return '₹${(n / 10000000).toStringAsFixed(2)} Cr';
    if (n >= 100000) return '₹${(n / 100000).toStringAsFixed(2)} L';
    if (n >= 1000) return '₹${(n / 1000).toStringAsFixed(1)}K';
    return '₹${n.toStringAsFixed(0)}';
  }

  void _toast(String msg, {bool error = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: error ? _danger : _ok,
      behavior: SnackBarBehavior.floating,
    ));
  }

  void _showAddExpenseDialog() {
    final formKey = GlobalKey<FormState>();
    final descC = TextEditingController();
    final amountC = TextEditingController();
    final voucherC = TextEditingController();
    String head = 'equipment';
    DateTime expenseDate = DateTime.now();
    bool saving = false;

    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setS) => AlertDialog(
          backgroundColor: _cardBg,
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
          title: const Text('Add Grant Expense',
              style:
                  TextStyle(color: Colors.white, fontWeight: FontWeight.w700)),
          content: SizedBox(
            width: 440,
            child: Form(
              key: formKey,
              child: SingleChildScrollView(
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  DropdownButtonFormField<String>(
                    initialValue: head,
                    dropdownColor: _cardBg,
                    style: const TextStyle(color: Colors.white),
                    decoration: InputDecoration(
                      filled: true,
                      fillColor: _cardBg2,
                      border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(10),
                          borderSide: BorderSide.none),
                      labelText: 'Expense Head',
                      labelStyle: const TextStyle(color: _textSec),
                    ),
                    items: _heads
                        .map((h) => DropdownMenuItem(
                            value: h,
                            child: Text(h.toUpperCase())))
                        .toList(),
                    onChanged: (v) => setS(() => head = v ?? head),
                  ),
                  const SizedBox(height: 12),
                  TextFormField(
                    controller: descC,
                    style: const TextStyle(color: Colors.white),
                    validator: (v) =>
                        (v == null || v.trim().isEmpty) ? 'Required' : null,
                    decoration: InputDecoration(
                      filled: true,
                      fillColor: _cardBg2,
                      border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(10),
                          borderSide: BorderSide.none),
                      labelText: 'Description',
                      labelStyle: const TextStyle(color: _textSec),
                      prefixIcon: const Icon(Icons.description_rounded,
                          color: _textSec, size: 20),
                    ),
                  ),
                  const SizedBox(height: 12),
                  Row(children: [
                    Expanded(
                      child: TextFormField(
                        controller: amountC,
                        style: const TextStyle(color: Colors.white),
                        keyboardType: TextInputType.number,
                        validator: (v) {
                          if (v == null || v.trim().isEmpty) return 'Required';
                          if (double.tryParse(v.trim()) == null) {
                            return 'Valid amount';
                          }
                          return null;
                        },
                        decoration: InputDecoration(
                          filled: true,
                          fillColor: _cardBg2,
                          border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(10),
                              borderSide: BorderSide.none),
                          labelText: 'Amount (₹)',
                          labelStyle: const TextStyle(color: _textSec),
                          prefixIcon: const Icon(Icons.currency_rupee_rounded,
                              color: _textSec, size: 20),
                        ),
                      ),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: TextFormField(
                        controller: voucherC,
                        style: const TextStyle(color: Colors.white),
                        decoration: InputDecoration(
                          filled: true,
                          fillColor: _cardBg2,
                          border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(10),
                              borderSide: BorderSide.none),
                          labelText: 'Voucher No',
                          labelStyle: const TextStyle(color: _textSec),
                          prefixIcon: const Icon(Icons.receipt_rounded,
                              color: _textSec, size: 20),
                        ),
                      ),
                    ),
                  ]),
                  const SizedBox(height: 12),
                  OutlinedButton.icon(
                    style: OutlinedButton.styleFrom(
                      foregroundColor: _textSec,
                      side: const BorderSide(color: _border),
                    ),
                    icon: const Icon(Icons.calendar_today_rounded, size: 16),
                    label: Text(
                        'Date: ${DateFormat('dd MMM yyyy').format(expenseDate)}'),
                    onPressed: () async {
                      final d = await showDatePicker(
                        context: ctx,
                        initialDate: expenseDate,
                        firstDate: DateTime(2015),
                        lastDate: DateTime(2100),
                      );
                      if (d != null) setS(() => expenseDate = d);
                    },
                  ),
                ]),
              ),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: const Text('Cancel', style: TextStyle(color: _textSec))),
            ElevatedButton(
              style: ElevatedButton.styleFrom(backgroundColor: _primary),
              onPressed: saving
                  ? null
                  : () async {
                      if (!formKey.currentState!.validate()) return;
                      setS(() => saving = true);
                      final ok = await _service.addGrantExpense({
                        'grant_id': _grantId,
                        'expense_head': head,
                        'description': descC.text.trim(),
                        'amount': double.tryParse(amountC.text.trim()) ?? 0,
                        'expense_date':
                            expenseDate.toIso8601String().split('T').first,
                        'voucher_no': voucherC.text.trim(),
                        'created_by': 'accountant',
                      });
                      if (!ctx.mounted) return;
                      Navigator.pop(ctx);
                      _toast(ok
                          ? 'Expense added — utilization updated'
                          : 'Failed to add expense',
                          error: !ok);
                      if (ok) _load();
                    },
              child:
                  const Text('Add', style: TextStyle(color: Colors.white)),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _bg,
      appBar: AppBar(
        backgroundColor: _cardBg,
        foregroundColor: Colors.white,
        elevation: 0,
        title: Text((widget.grant['title'] as String?) ?? 'Grant Detail',
            style: const TextStyle(fontWeight: FontWeight.w700),
            overflow: TextOverflow.ellipsis),
        actions: [
          IconButton(
              icon: const Icon(Icons.refresh_rounded),
              tooltip: 'Refresh',
              onPressed: _load),
        ],
      ),
      body: _isLoading
          ? const Center(child: CircularProgressIndicator(color: _primary))
          : ListView(
              padding: const EdgeInsets.all(16),
              children: [
                _buildUCCard(),
                const SizedBox(height: 16),
                GradientButton(
                  text: 'Add Expense',
                  icon: Icons.add_rounded,
                  onPressed: _showAddExpenseDialog,
                  gradient: const LinearGradient(
                    colors: [_primary, _accent],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                  height: 50,
                ),
                const SizedBox(height: 20),
                const Text('Head-wise Utilization',
                    style: TextStyle(
                        color: Colors.white,
                        fontSize: 15,
                        fontWeight: FontWeight.w700)),
                const SizedBox(height: 10),
                _buildHeadWise(),
                const SizedBox(height: 20),
                const Text('Expenses',
                    style: TextStyle(
                        color: Colors.white,
                        fontSize: 15,
                        fontWeight: FontWeight.w700)),
                const SizedBox(height: 10),
                if (_expenses.isEmpty)
                  const Padding(
                    padding: EdgeInsets.symmetric(vertical: 24),
                    child: Center(
                        child: Text('No expenses booked against this grant yet',
                            style: TextStyle(color: _textSec, fontSize: 13))),
                  )
                else
                  ..._expenses.map(_buildExpenseTile),
              ],
            ),
    );
  }

  Widget _buildUCCard() {
    final sanctioned = (_uc['sanctioned'] as num?)?.toDouble() ?? 0;
    final received = (_uc['received'] as num?)?.toDouble() ?? 0;
    final utilized = (_uc['utilized'] as num?)?.toDouble() ?? 0;
    final balance = (_uc['balance'] as num?)?.toDouble() ?? 0;
    final pct = (_uc['utilizationPct'] as num?)?.toDouble() ?? 0;
    return GlassCard(
      color: _cardBg,
      padding: const EdgeInsets.all(20),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        const Row(children: [
          Icon(Icons.description_rounded, color: _accent, size: 20),
          SizedBox(width: 8),
          Expanded(
            child: Text('Utilization Certificate (UC) Summary',
                style: TextStyle(
                    color: Colors.white,
                    fontSize: 15,
                    fontWeight: FontWeight.w700)),
          ),
        ]),
        const SizedBox(height: 4),
        Text(
          '${_uc['grantNo'] ?? widget.grant['grant_no'] ?? ''} • ${_uc['fundingAgency'] ?? widget.grant['funding_agency'] ?? ''} • PI: ${_uc['principalInvestigator'] ?? widget.grant['principal_investigator'] ?? ''}',
          style: const TextStyle(color: _textSec, fontSize: 12),
        ),
        const SizedBox(height: 16),
        Row(children: [
          Expanded(child: _ucStat('Sanctioned', sanctioned)),
          Expanded(child: _ucStat('Received', received)),
        ]),
        const SizedBox(height: 12),
        Row(children: [
          Expanded(child: _ucStat('Utilized', utilized)),
          Expanded(
              child: _ucStat('Balance', balance,
                  valueColor: balance < 0 ? _danger : _ok)),
        ]),
        const SizedBox(height: 14),
        ClipRRect(
          borderRadius: BorderRadius.circular(8),
          child: LinearProgressIndicator(
            value: (pct.clamp(0, 100)) / 100,
            minHeight: 8,
            backgroundColor: _border,
            valueColor: const AlwaysStoppedAnimation<Color>(_accent),
          ),
        ),
        const SizedBox(height: 6),
        Text('${pct.toStringAsFixed(1)}% of sanctioned amount utilized',
            style: const TextStyle(color: _textSec, fontSize: 12)),
      ]),
    );
  }

  Widget _ucStat(String label, double value, {Color? valueColor}) {
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(_formatCurrency(value),
          style: TextStyle(
              color: valueColor ?? Colors.white,
              fontSize: 17,
              fontWeight: FontWeight.w800)),
      const SizedBox(height: 2),
      Text(label, style: const TextStyle(color: _textSec, fontSize: 12)),
    ]);
  }

  Widget _buildHeadWise() {
    final headWise = (_uc['headWise'] as Map?) ?? {};
    if (headWise.isEmpty) {
      return const Text('No head-wise data yet',
          style: TextStyle(color: _textSec, fontSize: 13));
    }
    return GlassCard(
      color: _cardBg,
      padding: const EdgeInsets.all(16),
      child: Column(
        children: headWise.entries.map((e) {
          return Padding(
            padding: const EdgeInsets.symmetric(vertical: 6),
            child: Row(children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: _primary.withOpacity(0.12),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Icon(_headIcon(e.key.toString()),
                    color: _primary, size: 16),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Text(e.key.toString().toUpperCase(),
                    style: const TextStyle(color: Colors.white, fontSize: 13)),
              ),
              Text(_formatCurrency(e.value),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                      fontWeight: FontWeight.w700)),
            ]),
          );
        }).toList(),
      ),
    );
  }

  IconData _headIcon(String head) {
    switch (head) {
      case 'equipment':
        return Icons.computer_rounded;
      case 'manpower':
        return Icons.people_rounded;
      case 'consumables':
        return Icons.science_rounded;
      case 'travel':
        return Icons.flight_rounded;
      case 'overheads':
        return Icons.business_rounded;
      default:
        return Icons.category_rounded;
    }
  }

  Widget _buildExpenseTile(Map<String, dynamic> e) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: GlassCard(
        color: _cardBg,
        padding: const EdgeInsets.all(14),
        child: Row(children: [
          Container(
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: _primary.withOpacity(0.12),
              borderRadius: BorderRadius.circular(10),
            ),
            child: Icon(_headIcon((e['expense_head'] as String?) ?? 'other'),
                color: _primary, size: 18),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text((e['description'] as String?) ?? 'Expense',
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.w600)),
                  Text(
                    '${(e['expense_head'] as String?) ?? ''} • ${e['expense_date'] ?? ''}'
                    '${(e['voucher_no'] as String?)?.isNotEmpty ?? false ? ' • Voucher: ${e['voucher_no']}' : ''}',
                    style: const TextStyle(color: _textSec, fontSize: 11),
                  ),
                ]),
          ),
          Text(_formatCurrency(e['amount']),
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 14,
                  fontWeight: FontWeight.w700)),
        ]),
      ),
    );
  }
}
